import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { UserSession } from '../../src/entities/user-session.entity';
import { buildUserSession } from '../factories/user-session.factory';
import { User } from '../../src/entities/user.entity';
import { buildUser } from '../factories/user.factory';

describe('UserSession Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let userId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const userEntity = em.create(
      User,
      buildUser(),
    );
    await em.persistAndFlush(userEntity);
    userId = userEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    const entity = em.create(UserSession, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    const saved = em.create(UserSession, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(UserSession, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(UserSession, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    const saved = em.create(UserSession, data);
    await em.persistAndFlush(saved);
    saved.token = `updated-${Date.now()}`;
    await em.flush();
    const reloaded = await em.findOne(UserSession, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.token).toEqual(saved.token);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    const saved = em.create(UserSession, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(UserSession, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    await em.persistAndFlush(em.create(UserSession, data));
    const all = await em.find(UserSession, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('finds entity by unique field token', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId, token: `test-${Date.now()}` });
    const saved = em.create(UserSession, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(UserSession, {
      token: `test-${Date.now()}`,
    });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('persists with user foreign key', async () => {
    const em = orm.em.fork();
    const data = buildUserSession({ user: userId });
    const saved = em.create(UserSession, data);
    await em.persistAndFlush(saved);
    await em.populate(saved, ['user']);
    expect(saved.user.id).toBe(userId);
  });
});
